<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { genTypeApi, promptApi, taskApi } from '@/api/modules'
import { connectWs, onWsEvent } from '@/ws/client'
import GlassCard from '@/v2/components/GlassCard.vue'
import CopyButton from '@/v2/components/CopyButton.vue'
import DatePicker from '@/v2/components/DatePicker.vue'
import MediaViewer from '@/v2/components/MediaViewer.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import V2Field from '@/v2/components/V2Field.vue'
import TaskDetailDrawer from './TaskDetailDrawer.vue'
import { useTaskOutputThumbs } from './useTaskOutputThumbs'
import './task-output-thumbnails.css'
import { activeStatuses, flattenGenerationMenu, formatDate, statusMeta, todayRange, type GenerationTypeItem, type TaskItem, type TaskOutput } from './model'
const PAGE_SIZE=20
const route=useRoute();const router=useRouter();const tasks=ref<TaskItem[]>([]);const types=ref<GenerationTypeItem[]>([]);const outputs=ref<Record<number,TaskOutput[]>>({});const loading=ref(false);const loadError=ref('');const actionId=ref<number|null>(null);const bulkLoading=ref(false);const recheckingId=ref<number|null>(null);const selected=ref(new Set<number>());const keyword=ref('');const status=ref('');const typeId=ref('');const date=ref(todayRange().date);const page=ref(1);const total=ref(0);const detail=ref<TaskItem|null>(null);const preview=ref<TaskOutput|null>(null);const datePickerOpen=ref(false);const pendingRefreshIds=new Set<number>();let off:(()=>void)|null=null;let refreshTimer:ReturnType<typeof setTimeout>|null=null;let searchTimer:ReturnType<typeof setTimeout>|null=null;let loadVersion=0
const names=computed(()=>Object.fromEntries(types.value.map(v=>[v.id,v.name])));const filtered=computed(()=>tasks.value);const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/PAGE_SIZE)));const pageStart=computed(()=>total.value?(page.value-1)*PAGE_SIZE+1:0);const pageEnd=computed(()=>Math.min(page.value*PAGE_SIZE,total.value));const allSelected=computed(()=>filtered.value.length>0&&filtered.value.every(task=>selected.value.has(task.id)))
const {withThumbs,release}=useTaskOutputThumbs()
function queryParams(){const params:any={};if(keyword.value.trim())params.keyword=keyword.value.trim();if(status.value)params.status=status.value;if(typeId.value)params.generation_type_id=Number(typeId.value);if(date.value){const from=new Date(`${date.value}T00:00:00`);const to=new Date(from);to.setDate(to.getDate()+1);params.created_from=from.toISOString();params.created_to=to.toISOString()}return params}
async function load(){const version=++loadVersion;loading.value=true;loadError.value='';try{const params=queryParams();const offset=(page.value-1)*PAGE_SIZE;const list:TaskItem[]=await taskApi.list({...params,limit:PAGE_SIZE,offset});if(version!==loadVersion)return;const count=await taskApi.count(params).catch(()=>null);if(version!==loadVersion)return;total.value=count?Math.max(count.total,offset+list.length):offset+list.length+(list.length===PAGE_SIZE?1:0);if(!list.length&&page.value>1){page.value=Math.max(1,totalPages.value);void load();return}const visibleIds=new Set(list.map(task=>task.id));for(const id of Object.keys(outputs.value).map(Number)){if(!visibleIds.has(id)){release(outputs.value[id]);delete outputs.value[id]}}tasks.value=list;selected.value=new Set([...selected.value].filter(id=>visibleIds.has(id)));void loadPreviews(list,version)}catch(event:any){if(version!==loadVersion)return;loadError.value=event.response?.data?.detail||event.message||'任务加载失败'}finally{if(version===loadVersion)loading.value=false}}
async function loadPreviews(items:TaskItem[],version=loadVersion){const ids=items.filter(t=>t.status==='SUCCESS'&&!(outputs.value[t.id]?.length)).map(t=>t.id);if(!ids.length)return;try{const summaries=await taskApi.outputSummaries(ids);if(version!==loadVersion)return;for(const id of ids){release(outputs.value[id]);outputs.value[id]=await withThumbs(summaries[id]||[]);if(version!==loadVersion)return}}catch{/* previews are optional */}}
async function refreshTask(taskId:number){const index=tasks.value.findIndex(task=>task.id===taskId);if(index<0)return;try{const item=await taskApi.get(taskId);Object.assign(tasks.value[index],item);if(item.status==='SUCCESS'&&!outputs.value[taskId]?.length)void loadPreviews([item])}catch{/* a deleted task will disappear on manual refresh */}}
async function act(task:TaskItem,action:'cancel'|'retry'|'regenerate'|'delete'){actionId.value=task.id;try{if(action==='delete'){if(!confirm(`确定删除任务 #${task.id}？生成产物会保留在素材库。`))return;await taskApi.delete(task.id);release(outputs.value[task.id]);delete outputs.value[task.id]}else await taskApi[action](task.id);selected.value.delete(task.id);await load()}catch(e:any){alert(e.response?.data?.detail||e.message||'操作失败')}finally{actionId.value=null}}
async function recheck(task:TaskItem){recheckingId.value=task.id;try{const result=await taskApi.recheck(task.id);alert(result.message||'再检查完成');if(result.ok)await load()}catch(e:any){alert(e?.response?.data?.detail||e?.message||'再检查失败')}finally{recheckingId.value=null}}
const savingPromptId=ref<number|null>(null)
async function savePromptToLib(task:TaskItem){
  const text=String(task.params?.prompt||'').trim()
  if(!text){alert('提示词内容为空');return}
  const isNegative=false
  savingPromptId.value=task.id
  try{
    const gt=types.value.find(v=>v.id===task.generation_type_id)
    const mediaLabel=gt?.media_type==='video'?'视频':'图片'
    const categoryName=`${mediaLabel}提示词`
    const cats=await promptApi.listCategories() as any[]
    let cat=cats.find((c:any)=>c.name===categoryName)
    if(!cat)cat=await promptApi.createCategory(categoryName) as any
    const name=text.slice(0,20)+(text.length>20?'…':'')
    await promptApi.create({name,content:text,negative_content:'',category_id:cat.id,remark:`从任务 #${task.id} 添加`,tags:[]})
    alert(`已存入提示词库「${categoryName}」`)
  }catch(e:any){alert(typeof e==='string'?e:(e?.response?.data?.detail?String(e.response.data.detail):e?.message?String(e.message):'保存失败'))}
  finally{savingPromptId.value=null}
}
function toggle(taskId:number){const next=new Set(selected.value);next.has(taskId)?next.delete(taskId):next.add(taskId);selected.value=next}function toggleAll(){selected.value=allSelected.value?new Set():new Set(filtered.value.map(task=>task.id))}
async function bulk(action:'delete'|'cancel'|'retry'|'regenerate'){const ids=[...selected.value];if(!ids.length)return;const label={delete:'删除',cancel:'取消',retry:'重试',regenerate:'重新生成'}[action];if(!confirm(`对已选择的 ${ids.length} 个任务执行“${label}”？${action==='delete'?'生成产物会保留在素材库。':''}`))return;bulkLoading.value=true;try{const result=await taskApi.bulk(ids,action);selected.value=new Set();await load();alert(`批量${label}完成：成功 ${result.succeeded}，失败 ${result.failed.length}${result.failed.length?'\n'+result.failed.map((v:any)=>`#${v.task_id} ${v.reason}`).join('\n'):''}`)}catch(e:any){alert(e.response?.data?.detail||'批量操作失败')}finally{bulkLoading.value=false}}
function applyFilters(){page.value=1;void load()}function reset(){if(searchTimer)clearTimeout(searchTimer);keyword.value='';status.value='';typeId.value='';date.value=todayRange().date;applyFilters()}function changePage(next:number){if(next<1||next>totalPages.value||next===page.value||loading.value)return;page.value=next;void load();window.scrollTo({top:0,behavior:'smooth'})}
/** 快捷日期选择 */
function dateOffset(days:number){const d=new Date();d.setDate(d.getDate()+days);const y=d.getFullYear();const m=String(d.getMonth()+1).padStart(2,'0');const day=String(d.getDate()).padStart(2,'0');date.value=`${y}-${m}-${day}`;applyFilters()}
function clearDate(){date.value='';applyFilters()}
const todayStr=todayRange().date
const yesterdayStr=()=>{const d=new Date();d.setDate(d.getDate()-1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const dayBeforeStr=()=>{const d=new Date();d.setDate(d.getDate()-2);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function onTaskEvent(event:any){const taskId=Number(event?.task_id);if(!taskId||!tasks.value.some(task=>task.id===taskId))return;pendingRefreshIds.add(taskId);if(refreshTimer)clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{const ids=[...pendingRefreshIds];pendingRefreshIds.clear();void Promise.all(ids.map(refreshTask))},250)}
watch(keyword,()=>{if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(applyFilters,350)})
onMounted(async()=>{types.value=flattenGenerationMenu(await genTypeApi.menu());await load();const requested=Number(route.query.task);if(requested){const found=tasks.value.find(t=>t.id===requested);detail.value=found||await taskApi.get(requested)}connectWs();off=onWsEvent(onTaskEvent)});onUnmounted(()=>{off?.();if(refreshTimer)clearTimeout(refreshTimer);if(searchTimer)clearTimeout(searchTimer)})
</script>
<template><div class="v2-page"><div class="v2-page-heading heading"><div><StatusBadge tone="info">真实任务数据</StatusBadge><h1>任务管理</h1><p>默认显示当天任务，共 {{ total }} 项</p></div><V2Button :disabled="loading" @click="load">{{ loading?'刷新中…':'刷新' }}</V2Button></div><GlassCard padding="sm"><div class="filters"><V2Field label="关键词"><input v-model="keyword" placeholder="任务 ID、批次、提示词或错误"/></V2Field><V2Field label="状态"><select v-model="status" @change="applyFilters"><option value="">全部状态</option><option v-for="(meta,key) in statusMeta" :key="key" :value="key">{{ meta.label }}</option></select></V2Field><V2Field label="生成类型"><select v-model="typeId" @change="applyFilters"><option value="">全部类型</option><option v-for="type in types" :key="type.id" :value="type.id">{{ type.name }}</option></select></V2Field><V2Field label="创建日期"><div class="date-picker"><div class="quick-dates"><button :class="{active:date===todayStr}" @click="date=todayStr;applyFilters()">今天</button><button :class="{active:date===yesterdayStr()}" @click="dateOffset(-1)">昨天</button><button :class="{active:date===dayBeforeStr()}" @click="dateOffset(-2)">前天</button><button :class="{active:!date}" @click="clearDate()">全部</button></div><button class="date-display" @click="datePickerOpen=true">{{ date||'选择日期…' }} <span>📅</span></button></div></V2Field><V2Button variant="ghost" @click="reset">重置</V2Button></div></GlassCard><div class="bulk-bar" :class="{active:selected.size}"><label><input type="checkbox" :checked="allSelected" @change="toggleAll"/> 全选当前页</label><span>已选择 {{ selected.size }} 项</span><div><V2Button variant="ghost" :disabled="!selected.size||bulkLoading" @click="bulk('cancel')">批量取消</V2Button><V2Button variant="ghost" :disabled="!selected.size||bulkLoading" @click="bulk('retry')">批量重试</V2Button><V2Button variant="ghost" :disabled="!selected.size||bulkLoading" @click="bulk('regenerate')">批量重新生成</V2Button><V2Button variant="danger" :disabled="!selected.size||bulkLoading" @click="bulk('delete')">批量删除</V2Button></div></div>
<div v-if="loadError" class="load-error"><span>{{ loadError }}</span><V2Button variant="ghost" @click="load">重新加载</V2Button></div><div class="task-table"><div class="table-head"><span>选择</span><span>任务</span><span>状态</span><span>生成类型 / 提示词</span><span>预览</span><span>创建时间</span><span>操作</span></div><article v-for="task in filtered" :key="task.id" class="task-row" :class="{selected:selected.has(task.id)}"><label class="row-check"><input type="checkbox" :checked="selected.has(task.id)" @change="toggle(task.id)"/><span>选择任务 #{{ task.id }}</span></label><b>#{{ task.id }}<small>批次 {{ task.batch_id }} · 行 {{ task.row_no }}</small></b><StatusBadge :tone="statusMeta[task.status]?.tone">{{ statusMeta[task.status]?.label||task.status }}</StatusBadge><div class="type-prompt"><b>{{ names[task.generation_type_id||0]||'未分类' }}</b><small v-if="task.workflow_name" class="wf-name">{{ task.workflow_name }}</small><div class="prompt-line"><span>{{ task.params?.prompt||task.error||'无提示词' }}</span><CopyButton v-if="task.params?.prompt" :text="String(task.params.prompt)" size="sm" /><button v-if="task.params?.prompt" type="button" class="prompt-save-btn" :disabled="savingPromptId===task.id" @click="savePromptToLib(task)">{{ savingPromptId===task.id?'保存中…':'存入词库' }}</button></div></div><div class="previews"><button v-for="out in (outputs[task.id]||[]).slice(0,3)" :key="out.id" @click="preview=out"><img v-if="(out.media_type==='image'||out.media_type==='video')&&out.thumbUrl" :src="out.thumbUrl" loading="lazy" decoding="async"/><span v-else-if="out.media_type==='audio'">♪</span><span v-else-if="out.media_type==='text'">文</span><span v-else class="thumb-pending">▧</span><i v-if="out.media_type==='video'">▶</i></button><small v-if="!(outputs[task.id]||[]).length">—</small></div><time>{{ formatDate(task.created_at) }}</time><div class="actions"><button @click="detail=task;router.replace({query:{...route.query,task:task.id}})">详情</button><button v-if="activeStatuses.includes(task.status)" @click="act(task,'cancel')">取消</button><button v-if="['FAILED','CANCELLED'].includes(task.status)" @click="act(task,'retry')">重试</button><button v-if="task.status==='FAILED'" :disabled="recheckingId===task.id" @click="recheck(task)">{{ recheckingId===task.id?'检查中…':'再检查' }}</button><button v-if="['SUCCESS','FAILED'].includes(task.status)" @click="act(task,'regenerate')">重新生成</button><button class="danger" :disabled="actionId===task.id" @click="act(task,'delete')">{{ actionId===task.id?'删除中…':'删除' }}</button></div></article><div v-if="!filtered.length&&!loading&&!loadError" class="empty">当前条件下没有任务</div></div>
<nav v-if="total" class="pagination" aria-label="任务分页"><span>显示 {{ pageStart }}–{{ pageEnd }} 条，共 {{ total }} 条</span><div><V2Button variant="ghost" :disabled="page===1||loading" @click="changePage(page-1)">上一页</V2Button><b>第 {{ page }} / {{ totalPages }} 页</b><V2Button variant="ghost" :disabled="page===totalPages||loading" @click="changePage(page+1)">下一页</V2Button></div></nav><TaskDetailDrawer :open="!!detail" :task="detail" @close="detail=null;router.replace({query:{}})" @changed="load"/><DatePicker :open="datePickerOpen" v-model="date" @close="datePickerOpen=false" @update:model-value="applyFilters()" /><MediaViewer :open="!!preview" :output="preview" @close="preview=null"/></div></template>
<style scoped>.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:16px}.heading h1{margin-top:14px}.filters{display:grid;grid-template-columns:2fr 1fr 1.2fr 1fr auto;align-items:end;gap:10px}.date-picker{display:grid;gap:6px}.quick-dates{display:flex;gap:4px;flex-wrap:wrap}.quick-dates button{padding:4px 10px;font-size:11px;color:var(--v2-text-muted);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:7px;cursor:pointer;white-space:nowrap}.quick-dates button.active{color:var(--v2-primary);border-color:var(--v2-primary);background:rgba(130,149,255,.12)}.date-picker input[type="date"],.date-select,.date-display{width:100%;min-height:36px;padding:0 10px;display:flex;align-items:center;justify-content:space-between;font-size:13px;color:var(--v2-text);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:8px;cursor:pointer}.bulk-bar{margin-top:14px;padding:10px 14px;display:flex;align-items:center;gap:16px;background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:12px;color:var(--v2-text-muted)}.bulk-bar.active{border-color:rgba(130,149,255,.45);background:rgba(130,149,255,.09)}.bulk-bar label{display:flex;align-items:center;gap:7px}.bulk-bar>div{margin-left:auto;display:flex;gap:7px;flex-wrap:wrap}.load-error{margin-top:12px;padding:12px 14px;display:flex;align-items:center;justify-content:space-between;gap:12px;color:var(--v2-danger);background:rgba(255,127,145,.08);border:1px solid rgba(255,127,145,.25);border-radius:12px}.task-table{margin-top:12px;overflow:hidden;background:var(--v2-surface);border:1px solid var(--v2-border);border-radius:var(--v2-radius-lg);box-shadow:var(--v2-shadow-soft);backdrop-filter:blur(var(--v2-blur))}.table-head,.task-row{display:grid;grid-template-columns:42px 78px 90px minmax(180px,1fr) 158px 152px 220px;gap:10px;align-items:center}.table-head{min-height:44px;padding:0 14px;color:var(--v2-text-subtle);font-size:11px;border-bottom:1px solid var(--v2-border)}.task-row{min-height:86px;padding:10px 14px;border-bottom:1px solid var(--v2-border)}.task-row.selected{background:rgba(130,149,255,.06)}.row-check{display:grid;place-items:center}.row-check span{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.row-check input{width:17px;height:17px}.task-row> b{display:grid;gap:5px}.task-row> b small,.type-prompt span,time{color:var(--v2-text-muted);font-size:11px}.type-prompt{min-width:0;display:grid;gap:5px}.wf-name{color:var(--v2-primary);font-size:10px;opacity:.8}.prompt-line{display:flex;align-items:center;gap:6px;min-width:0}.type-prompt span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.prompt-save-btn{flex-shrink:0;padding:1px 8px;font-size:10px;color:var(--v2-primary);background:rgba(130,149,255,.1);border:1px solid rgba(130,149,255,.2);border-radius:6px;cursor:pointer;white-space:nowrap}.prompt-save-btn:hover:not(:disabled){background:rgba(130,149,255,.2)}.prompt-save-btn:disabled{opacity:.5;cursor:not-allowed}.previews{display:flex;gap:5px}.previews button{width:48px;height:48px;padding:0;position:relative;display:grid;place-items:center;color:var(--v2-text);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:8px;overflow:hidden;cursor:pointer}.previews img{width:100%;height:100%;object-fit:contain}.previews i{position:absolute;font-style:normal;text-shadow:0 1px 3px #000}.actions{display:flex;flex-wrap:wrap;gap:5px}.actions button{padding:5px 8px;color:var(--v2-text-muted);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:7px;cursor:pointer}.actions .danger{color:var(--v2-danger)}.empty{padding:70px;text-align:center;color:var(--v2-text-muted)}.pagination{margin-top:14px;padding:12px 14px;display:flex;align-items:center;justify-content:space-between;gap:16px;color:var(--v2-text-muted);background:var(--v2-surface);border:1px solid var(--v2-border);border-radius:14px}.pagination>div{display:flex;align-items:center;gap:10px}.pagination b{min-width:88px;text-align:center;color:var(--v2-text);font-size:12px}@media(max-width:1100px){.filters{grid-template-columns:2fr 1fr 1fr}.filters>*:nth-child(4),.filters>*:nth-child(5){grid-column:auto}.table-head{display:none}.task-row{margin:10px;grid-template-columns:34px 75px 90px 1fr 150px;border:1px solid var(--v2-border);border-radius:14px}.task-row time{display:none}.actions{grid-column:4/6}.previews{grid-row:1/3;grid-column:5}}@media(max-width:700px){.filters{grid-template-columns:1fr 1fr}.filters>*:first-child{grid-column:span 2}.filters>*:nth-child(4){grid-column:span 2}.quick-dates button{padding:6px 12px;font-size:12px;min-height:32px}.bulk-bar{align-items:flex-start;flex-wrap:wrap}.bulk-bar>div{width:100%;margin-left:0}.bulk-bar>div>*{flex:1}.load-error{align-items:stretch;flex-direction:column}.task-table{background:transparent;border:0;box-shadow:none}.task-row{padding:14px;grid-template-columns:34px 1fr auto}.row-check{grid-column:1}.task-row> b{grid-column:2}.task-row>.badge{grid-column:3}.type-prompt,.previews,.actions{grid-column:1/4}.previews{grid-row:auto}.previews button{width:64px;height:64px}.pagination{align-items:stretch;flex-direction:column}.pagination>div{justify-content:space-between}}</style>
